from lib import *
S = SS('s12')
steps = [
    step("内置的爬虫中间件按数字(离引擎近 → 远):Start 25、HttpError 50、Referer 700、UrlLength 800、Depth 900、MetaCopyDetection 1000。再加三个自定义的 A=100、B=300、C=950:process_start 依次是 A B C;process_spider_input 也是 A B C(从引擎一侧向 spider 一侧,数字从小到大),然后才是回调;回调产出的东西走 process_spider_output 时反过来 C B A(从 spider 一侧回到引擎)。每个 item 和 Request 都单独走一遍这条链。", t=tl(S(1)), mark=lidx(S(1), 'C       process_spider_output', 'A       process_spider_output'), done=lidx(S(1), 'process_start', 'process_spider_input', 'spider  callback'), kv=KV([['process_start / input', '数字从小到大:A B C'], ['process_spider_output', '数字从大到小:C B A'], ['内置', 'Start 25 … MetaCopy 1000']], ['process_spider_output'])),
    step("process_spider_input 里抛异常(B=300):回调被跳过,Failure 直接交给 errback(消息 ValueError: input rejected by B);C 的 process_spider_input 不会被调用;process_spider_exception 也不会被调用,spider_exceptions/count = 0——这一步的错误不算 spider 异常。HttpErrorMiddleware 拒绝 404 就是用的这条路径(s6 里的 HttpError)。", t=tl(S(2)), mark=lidx(S(2), 'errback', 'B       process_spider_input'), done=lidx(S(2), 'A       process_spider_input'), kv=KV([['B 的 input 抛异常', 'C 的 input 不再调用,回调跳过'], ['去向', '直接进 errback'], ['process_spider_exception', '不调用'], ['spider_exceptions/count', '0']], ['B 的 input 抛异常'])),
    step("process_spider_output 可以过滤:A 丢掉 /i1、/i3 两个请求和 price < 0 的 item,服务器只收到 /list、/i2、/i0(后产生的 i2 先请求,LIFO),item_scraped_count = 1。每个对象都先进 process_spider_output 再决定放不放行,被丢弃的不会进调度器也不会进 pipeline。", t=tl(S(3)), mark=lidx(S(3), '丢弃'), done=lidx(S(3), 'Request i0', 'Request i2', "item {'price': 5}"), kv=KV([['丢弃的请求', 'i1、i3(不进调度器)'], ['丢弃的 item', 'price = -1'], ['服务器', '/list /i2 /i0'], ['item_scraped_count', '1']], ['丢弃的请求'])),
    step("回调抛异常:先 yield 的 item {'n': 1} 照常过 C B A 放行;异常发生后 process_spider_exception 按 C、B、A 的顺序调用(spider 一侧到引擎一侧);没有人处理,最后是 spider_exceptions/count = 1(日志里的 Spider error processing)。让 B 返回 [{'recovered_by': 'B'}]:链在 B 处终止,A 的 process_spider_exception 不再调用,恢复出来的 item 只经过 A 的 process_spider_output(B、C 已经处理过),item_scraped_count = 2,spider_exceptions/count = 0。", t=tl(S(4)), mark=lidx(S(4), 'process_spider_exception', 'recovered_by'), done=lidx(S(4), 'spider  callback'), kv=KV([['异常链', 'C → B → A(spider 一侧到引擎一侧)'], ['返回 None', '继续交给下一个'], ['返回可迭代对象', '终止异常链,内容只走更靠近引擎的 output'], ['恢复后', 'spider_exceptions/count = 0']], ['返回可迭代对象'])),
    step("2.19 要求 process_spider_output 是异步的:只写旧的同步版本 Old,启动就抛 TypeError: Middleware spider.Old doesn't support asynchronous spider output. Its process_spider_output() method should be an async generator function or it should additionally define a process_spider_output_async() method.;同步版本再加上 process_spider_output_async 的 New 就能运行,异步版本被调用,item_scraped_count = 1。", t=tl(S(5)), mark=lidx(S(5), 'Old', 'New'), kv=KV([['只有同步 process_spider_output', '启动时 TypeError'], ['加 process_spider_output_async', '正常,异步版本被调用'], ['或直接写 async 生成器', '同样可以']], ['只有同步 process_spider_output'])),
    step("两个内置中间件的效果:HttpErrorMiddleware 把 404 响应拦下来,日志 “Ignoring response <404 …>: HTTP status code is not handled or not allowed”,httperror/response_ignored_count = 1、httperror/response_ignored_status_count/404 = 1,回调只被调用了 /ok 一次;UrlLengthMiddleware 丢掉长 3000 的 URL,日志 “Ignoring link (url length > 2083)”,urllength/request_ignored_count = 1,服务器没有收到它。", t=tl(S(6)), mark=lidx(S(6), '回调被调用的', 'stats:', '日志'), kv=KV([['404', 'HttpError 拦截,回调不调用'], ['URL 长度 > 2083', 'UrlLength 丢弃,不请求'], ['计数', 'httperror/*、urllength/request_ignored_count']], ['404'])),
]
A = mkarts('s12', 12, 'Scrapy,爬虫中间件,process_spider_input,process_spider_output,process_spider_exception,真实验证,动画演示',
    '实测 Scrapy 2.19 爬虫中间件:input 从小到大、output 从大到小;input 抛异常直接进 errback 且不算 spider 异常;output 可以过滤请求和 item;process_spider_exception 按 C、B、A 调用,返回可迭代对象即可终止;同步版 process_spider_output 在 2.19 启动即 TypeError。',
    '爬虫中间件夹在引擎和 spider 之间,管的是“进入回调的响应”和“回调产出的请求与 item”。这篇用三个自定义中间件加记录钩子,把输入、输出、异常三条链的方向与短路规则一条条实测出来。',
    [('C B A', 'process_spider_output 与 process_spider_exception 的调用顺序(input 是 A B C)'), ('TypeError', '2.19 里只写同步 process_spider_output 的启动结果'), ('0', 'process_spider_input 抛异常后 spider_exceptions/count 的值(直接进 errback)')],
    [('三条链', '<p>响应进来走 <code>process_spider_input</code>(数字小 → 大),回调产出走 <code>process_spider_output</code>(数字大 → 小),<code>process_start</code> 处理 <code>start()</code> 的输出。</p>'),
     ('input 抛异常', '<p>在 <code>process_spider_input</code> 里抛异常会跳过回调和更靠后的 input 方法,Failure 直接交给请求的 errback。<code>HttpErrorMiddleware</code> 就是这么拒绝非 2xx 响应的。</p>'),
     ('过滤产出', '<p><code>process_spider_output</code> 对每个请求和 item 单独决定放行与否,丢弃的对象不会进入调度器或 pipeline。</p>'),
     ('异常处理链', '<p>回调抛异常后,各中间件的 <code>process_spider_exception</code> 依次被调用:返回 <code>None</code> 交给下一个,返回可迭代对象则终止异常链,内容只经过更靠近引擎的 output。</p>'),
     ('异步要求', '<p>2.19 不接受只有同步 <code>process_spider_output</code> 的中间件:要写成 async 生成器,或再定义 <code>process_spider_output_async</code>。</p>'),
     ('内置中间件', '<p><code>HttpError</code> 过滤非 2xx 响应,<code>UrlLength</code> 丢弃过长的 URL,都会在 stats 里计数。</p>')],
    steps,
    [ENV_Y + '。中间件用工厂函数生成并通过 custom_settings 加入,每个钩子往 events.jsonl 记一行;内置顺序取自 SPIDER_MIDDLEWARES_BASE',
     '没有验证:process_spider_exception 写成异步生成器时的行为(试过一次:异步生成器对象会被当成可迭代对象而终止异常链,不是推荐用法);Referer、Depth、MetaCopyDetection 三个内置中间件的细节(Depth 见后面的文章);与 spider_middleware 里 from_crawler / NotConfigured 的组合;process_start 的异常处理'],
    '爬虫中间件')
